INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (367460, 15445, 'The Times of India', 'en', 'Rupee slips 7 paise against US dollar as crude soars beyond $90 per barrel levels', 'https://timesofindia.indiatimes.com/business/india-business/rupee-slips-7-paise-against-us-dollar-as-crude-soars-beyond-90-per-barrel-levels/articleshow/133311523.cms', 'On Tuesday morning, the Indian rupee experienced a drop against the US dollar, influenced by rising crude oil prices and persistent demand for dollars. Brent crude futures remained above ninety-one dollars per barrel, amplifying the necessity for dollars. Compounding this issue was the Reserve Bank''s recent closure of a forex-swap facility, which affected inflows. Additionally, domestic equities opened on a low note as foreign investors continued to sell shares.', 'https://static.toiimg.com/photo/msid-133311550,imgsize-29698.cms', '2026-08-18T04:32:28+00:00', '2026-08-18T04:49:02.722915'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
