INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (367751, 15445, 'The Economic Times', 'en', 'Global Market: Japan’s 10-year JGB yield hits three-decade high on BOJ rate hike bets', 'https://economictimes.indiatimes.com/markets/us-stocks/news/global-market-japans-10-year-jgb-yield-hits-three-decade-high-on-boj-rate-hike-bets/articleshow/133311165.cms', 'Japan’s 10-year government bond yield climbed to its highest level since 1996, driven by rising global bond yields, renewed inflation concerns and growing expectations of a Bank of Japan rate hike as early as September. The move highlights increasing pressure on Japan’s bond market as investors reassess the outlook for monetary policy.', 'https://img.etimg.com/photo/msid-133311165,imgsize-140448.cms', '2026-08-18T04:02:23+00:00', '2026-08-18T04:52:09.528701'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (367752, 15445, 'The Economic Times', 'en', 'Sensex falls over 250 points, Nifty below 24,250 as Mideast peace hopes fade. More pain ahead?', 'https://economictimes.indiatimes.com/markets/stocks/news/sensex-falls-over-250-points-nifty-below-24250-as-mideast-peace-hopes-fade-more-pain-ahead/articleshow/133310897.cms', 'Indian stock markets saw a troubling trend as they recorded declines for several days in a row. On the third straight day, the Sensex dropped significantly, and the Nifty 50 fell for the sixth consecutive session. This decline coincided with fading expectations for a peace deal in the Middle East, with the Sensex losing over 250 points and Nifty 50 dropping below 23,250 while small-cap stocks managed to gain traction.', 'https://img.etimg.com/photo/msid-133310897,imgsize-51120.cms', '2026-08-18T03:55:20+00:00', '2026-08-18T04:52:09.540985'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
