INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (371202, 15451, 'Al Jazeera English', 'en', 'Canada battles the clock, politics in scramble to avert Trump’s tariffs', 'https://www.aljazeera.com/economy/2026/8/18/canada-battles-the-clock-politics-in-scramble-to-avert-trumps-tariffs?traffic_source=rss', 'Canadian officials are making a last-ditch effort to negotiate a reprieve from 50-percent tariffs.', '', '2026-08-18T07:41:41+00:00', '2026-08-18T08:20:03.781086'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (371878, 15451, 'The Guardian', 'en', 'Top Democrats tussle in Florida primary but progressive liberalism not on menu', 'https://www.theguardian.com/us-news/2026/aug/18/florida-primary-election-senate-governor-races', 'Politics that worked for Democratic candidates in New York, Minnesota, Michigan won’t cut it in red Florida, analysts say If primary elections elsewhere this summer were tussles between progressives and moderates for the direction of the Democratic party’s political future, Tuesday’s contests in Florida could not be more different. In a former swing state that has in recent years become reliably red, moderate Democratic candidates Alex Vindman and David Jolly are heavily favored to become the party’s nominees for November’s Senate and governor’s race, respectively. Continue reading...', 'https://i.guim.co.uk/img/media/268c3a3e9aea2f24c7d22346259d4928d2e6b6aa/0_0_5000_4000/master/5000.jpg?width=140&quality=85&auto=format&fit=max&s=835b78e52c8629d2de8c566faa29a79d', '2026-08-18T09:00:21+00:00', '2026-08-18T09:14:52.259402'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
